import{c as a,Q as e,j as l,m as d}from"./chunks/framework.DOi4mjdC.js";const s="/assets/ND2NZ%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%88half%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%EF%BC%89.Dxu_qDb5.png",n="/assets/enableSmallC0%E5%BC%80%E5%90%AF%E6%A8%A1%E5%BC%8F%E4%B8%8B%E7%9A%84ND2NZ%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE-%EF%BC%88half%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%EF%BC%89.Bvj3jOlu.png",b=JSON.parse('{"title":"随路转换ND2NZ搬运","description":"","frontmatter":{},"headers":[{"level":1,"title":"随路转换ND2NZ搬运","slug":"随路转换nd2nz搬运"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"支持的通路和数据类型","slug":"支持的通路和数据类型"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换ND2NZ搬运.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换ND2NZ搬运.md"}'),r={name:"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换ND2NZ搬运.md"};function i(o,t,p,c,h,_){return e(),l("div",null,[...t[0]||(t[0]=[d(`<h1 id="随路转换nd2nz搬运" tabindex="-1">随路转换ND2NZ搬运 <a class="header-anchor" href="#随路转换nd2nz搬运" aria-label="Permalink to &quot;随路转换ND2NZ搬运&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持 Global Memory -&gt; Local Memory</th><th>是否支持 Local Memory -&gt; Local Memory</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td><td>x</td></tr><tr><td>Kirin 9030</td><td>√</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>支持在数据搬运时进行ND到NZ格式的转换。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>Global Memory -&gt; Local Memory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void DataCopy(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src, const Nd2NzParams&amp; intriParams)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 该函数原型仅支持Ascend 950PR/Ascend 950DT</span></span>
<span class="line"><span>template &lt;typename T, bool enableSmallC0 = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void DataCopy(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src, const Nd2NzParams&amp; intriParams)</span></span></code></pre></div></li><li><p>Local Memory -&gt; Local Memory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;   </span></span>
<span class="line"><span>__aicore__ inline void DataCopy(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const Nd2NzParams&amp; intriParams)</span></span></code></pre></div></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>各原型支持的具体数据通路和数据类型，请参考<a href="#section87413163309">支持的通路和数据类型</a>。</p></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。支持的数据类型请参考支持的通路和数据类型。</td></tr><tr><td>enableSmallC0</td><td>SmallC0模式开关：当dValue小于等于4的时候，C0_SIZE会补齐到4 * sizeof(T) Bytes。 默认不开启。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，类型为Nd2NzParams。 具体定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_data_copy.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Nd2NzParams结构体参数定义</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>传输ND矩阵的数目，取值范围：ndNum∈[0, 4095]。</td></tr><tr><td>nValue</td><td>ND矩阵的行数，取值范围：nValue∈[0, 16384]。</td></tr><tr><td>dValue</td><td>ND矩阵的列数，取值范围：dValue∈[0, 65535]。</td></tr><tr><td>srcNdMatrixStride</td><td>源操作数相邻ND矩阵起始地址间的偏移，取值范围：srcNdMatrixStride∈[0, 65535]，单位为元素。</td></tr><tr><td>srcDValue</td><td>源操作数同一ND矩阵的相邻行起始地址间的偏移，取值范围：srcDValue∈[1, 65535]，单位为元素。</td></tr><tr><td>dstNzC0Stride</td><td>ND转换到NZ格式后，源操作数中的一行会转换为目的操作数的多行。dstNzC0Stride表示，目的NZ矩阵中，来自源操作数同一行的多行数据相邻行起始地址间的偏移，取值范围：dstNzC0Stride∈[1, 16384]，单位：C0_SIZE（32B）。</td></tr><tr><td>dstNzNStride</td><td>目的NZ矩阵中，Z型矩阵相邻行起始地址之间的偏移。取值范围：dstNzNStride∈[1, 16384]，单位：C0_SIZE（32B）。</td></tr><tr><td>dstNzMatrixStride</td><td>目的NZ矩阵中，相邻NZ矩阵起始地址间的偏移，取值范围：dstNzMatrixStride∈[1, 65535]，单位为元素。</td></tr></tbody></table><p>ND2NZ转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示传输ND矩阵的数目为2 (ND矩阵1为A1~A2 + B1~B2，ND矩阵2为C1~C2 + D1~D2)。</li><li>nValue = 2，ND矩阵的行数，也就是矩阵的高度为2。</li><li>dValue = 24，ND矩阵的列数，也就是矩阵的宽度为24个元素。当dValue不满足32B对齐时，在目的操作数中不足的部分会被补齐为0，例如图示中A2所在DataBlock的空白部分会被补齐为0。</li><li>srcNdMatrixStride = 144，表达相邻ND矩阵起始地址间的偏移，即为A1~C1的距离，即为9个DataBlock，9 * 16 = 144个元素。</li><li>srcDValue = 48，表示一行的所含元素个数，即为A1到B1的距离，即为3个DataBlock，3 * 16 = 48个元素</li><li>dstNzC0Stride = 11。ND转换到NZ格式后，源操作数中的一行会转换为目的操作数的多行，例如src中A1和A2为1行，dst中A1和A2被分为2行。多行数据起始地址之间的偏移就是A1和A2在dst中的偏移，偏移为11个DataBlock。</li><li>dstNzNStride = 2，表示src中一个ND矩阵的第x行和第x+1行转换为NZ格式后在dst中的偏移，即A1和B1在dst之间的偏移为2个DataBlock。</li><li>dstNzMatrixStride = 96，表达dst中第x个ND矩阵的起点和第x+1个ND矩阵的起点的偏移，即A1和C1之间的距离，即为6个DataBlock，6 * 16 = 96个元素。</li></ul><p><strong>图 1</strong> ND2NZ转换示意图（half数据类型）<br><img src="`+s+'" alt="" title="ND2NZ转换示意图（half数据类型）"></p><p>enableSmallC0开启模式下的ND2NZ转换示意图如下：</p><p><strong>图 2</strong> enableSmallC0开启模式下的ND2NZ转换示意图 （half数据类型）<br><img src="'+n+`" alt="" title="enableSmallC0开启模式下的ND2NZ转换示意图-（half数据类型）"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>针对Atlas 推理系列产品AI Core，使用Global Memory -&gt; Local Memory通路的ND2NZ搬运接口时，需要预留8K的UB空间，作为接口的临时数据存放区。</p><h2 id="支持的通路和数据类型" tabindex="-1">支持的通路和数据类型 <a class="header-anchor" href="#支持的通路和数据类型" aria-label="Permalink to &quot;支持的通路和数据类型&quot;">​</a></h2><p>下文的数据通路均通过逻辑位置<a href="./../../../其他数据类型/TPosition.html#table5376122715308">TPosition</a>来表达，并注明了对应的物理通路。TPosition与物理内存的映射关系见<a href="./../../../通用说明和约束.html#table07372185712">表1</a>。</p><p><strong>表 4</strong> Global Memory -&gt; Local Memory具体通路和支持的数据类型</p><table tabindex="0"><thead><tr><th>产品型号</th><th>数据通路</th><th>源操作数和目的操作数的数据类型 (两者保持一致)</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32</td></tr><tr><td>Ascend 950PR/Ascend 950DT</td><td>GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>bool、int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、float</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>int16_t、uint16_t、int32_t、uint32_t、half、float</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>GM -&gt; VECIN（GM -&gt; UB）GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>GM -&gt; VECIN（GM -&gt; UB）GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Kirin X90</td><td>GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>half、int8_t、uint8_t、int16_t、uint16_t</td></tr><tr><td>Kirin 9030</td><td>GM -&gt; A1、B1（GM -&gt; L1 Buffer）</td><td>half、int8_t、uint8_t、int16_t、uint16_t</td></tr></tbody></table><p><strong>表 5</strong> Local Memory -&gt; Local Memory具体通路和支持的数据类型</p><table tabindex="0"><thead><tr><th>产品型号</th><th>数据通路</th><th>源操作数和目的操作数的数据类型 (两者保持一致)</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>VECIN、VECCALC、VECOUT -&gt; TSCM（UB -&gt; L1 Buffer）</td><td>bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>VECIN、VECCALC、VECOUT -&gt; TSCM（UB -&gt; L1 Buffer）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>VECIN、VECCALC、VECOUT -&gt; TSCM（UB -&gt; L1 Buffer）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr></tbody></table><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>intriParams参数解析请参考<a href="#fig128961542184620">图1</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// srcLocal为half类型的L1 Buffer空间上的LocalTensor，workLocal为half类型的UB空间上的LocalTensor，srcGlobal为half类型的GlobalTensor</span></span>
<span class="line"><span>AscendC::Nd2NzParams intriParams{1, 32, 32, 0, 32, 32, 1, 0};</span></span>
<span class="line"><span>// Global Memory -&gt; Local Memory</span></span>
<span class="line"><span>AscendC::DataCopy(srcLocal, srcGlobal, intriParams);</span></span>
<span class="line"><span>// Local Memory -&gt; Local Memory</span></span>
<span class="line"><span>AscendC::DataCopy(srcLocal, workLocal, intriParams);</span></span></code></pre></div><p>结果示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcGlobal): [1 2 3 ... 1024]</span></span>
<span class="line"><span>输出数据(dstGlobal):[1 2 ... 15 16 33 34 ... 47 48 65 66 ... 79 80 97 98 ... 111 112 ... 1009 1010... 1023 1024]</span></span></code></pre></div>`,35)])])}const m=a(r,[["render",i]]);export{b as __pageData,m as default};
